import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Send, User, Mail, MessageSquare } from 'lucide-react';

function Contact() {
    const [status, setStatus] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        // In a real app, this would use a service like Formspree or EmailJS
        // For now, we simulate the action
        setStatus('Sending...');
        setTimeout(() => {
            setStatus('Message Shipped Successfully.');
            e.target.reset();
        }, 1500);
    };

    return (
        <section className="contact-section">
            <span className="section-label">Get In Touch</span>
            <div className="contact-container">
                <motion.div
                    initial={{ opacity: 0, x: -20 }}
                    whileInView={{ opacity: 1, x: 0 }}
                    viewport={{ once: true }}
                    className="contact-info-text"
                >
                    <h2 className="contact-title">Let's build <br /> something <span className="accent-text">great</span>.</h2>
                    <p className="contact-desc">
                        Have a project in mind? We'd love to hear from you.
                        Our team is ready to transform your ideas into reality.
                    </p>
                </motion.div>

                <motion.form
                    initial={{ opacity: 0, x: 20 }}
                    whileInView={{ opacity: 1, x: 0 }}
                    viewport={{ once: true }}
                    className="contact-form"
                    onSubmit={handleSubmit}
                >
                    <div className="input-group">
                        <User className="input-icon" size={18} />
                        <input type="text" placeholder="YOUR NAME" required />
                    </div>
                    <div className="input-group">
                        <Mail className="input-icon" size={18} />
                        <input type="email" placeholder="EMAIL ADDRESS" required />
                    </div>
                    <div className="input-group textarea-group">
                        <MessageSquare className="input-icon" size={18} />
                        <textarea placeholder="PROJECT DETAILS / MESSAGE" required></textarea>
                    </div>

                    <motion.button
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        type="submit"
                        className="submit-btn"
                    >
                        {status || 'SEND MESSAGE'}
                        <Send size={18} style={{ marginLeft: 10 }} />
                    </motion.button>
                </motion.form>
            </div>
        </section>
    );
}

export default Contact;
